css:
.tx-att { font-family: Arial, Helvetica, sans-serif; color: #0f2a52; font-size: 8pt; line-height: 1.25; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.tx-att table { border-collapse: collapse; width: 100%; }
.tx-att td, .tx-att th { vertical-align: middle; }
.tx-att table.tx-inner { width: auto; }

.tx-logo-row { padding: 0 0 4px 4px; }
.tx-logo { width: 168px !important; height: 56px !important; max-width: none !important; display: block; }
.tx-rule { border-top: 2px solid #1b5fbf; margin: 4px 0 10px 0; }

.tx-att table.tx-bars { border-collapse: separate; border-spacing: 0; width: 100%; }
.tx-bar { background: #e8f0fc; border: 1px solid #d3e1f6; border-radius: 12px; padding: 7px 14px; }
.tx-bar-print { width: 20%; }
.tx-bar-gap { width: 2%; }
.tx-ico { padding-right: 12px; }
.tx-ico-s { padding-right: 6px; }
.tx-vdiv { width: 0; border-left: 1.5px solid #1b4079; height: 30px; padding: 0; margin: 0 14px 0 2px; }
.tx-vdiv-s { border-left: 1px solid #1b4079; height: 18px; }
.tx-vdiv + td { padding-left: 14px; }
.tx-vdiv-s + td { padding-left: 16px; }
.tx-vdiv-s { padding-left: 0; }
.tx-meta-cell { padding-right: 16px; }
.tx-title { font-size: 17pt; font-weight: bold; letter-spacing: 0.5px; text-transform: uppercase; color: #12306a; line-height: 1.1; }
.tx-period { font-size: 12pt; font-weight: bold; color: #12306a; margin-top: 1px; }
.tx-printed-k { font-size: 8.5pt; color: #12306a; }
.tx-printed-v { font-size: 10.5pt; font-weight: bold; color: #12306a; }

.tx-infobar { margin: 8px 0 12px 0; }
.tx-bar-info { padding: 5px 14px; }
.tx-meta-cell { white-space: nowrap; font-size: 9.5pt; }
.tx-meta-k { color: #12306a; }
.tx-meta-v { font-weight: bold; color: #1b4079; }
.tx-meta-active { color: #16a34a; }

.tx-grid-wrap { border: 1px solid #c9d8ee; border-radius: 10px; overflow: hidden; margin-top: 8px; }
.tx-att table.tx-grid { table-layout: fixed; border-collapse: collapse; }
.tx-grid th, .tx-grid td { padding: 3px 2px; overflow: hidden; }
.tx-grid thead { display: table-header-group; }
.tx-grid tr { page-break-inside: avoid; }
.tx-grid th { background: #1b4079; color: #fff; font-size: 7pt; font-weight: bold; text-align: center; text-transform: uppercase; height: 28px; letter-spacing: 0.2px; }
.tx-grid th.tx-left, .tx-grid td.tx-left { text-align: left; padding-left: 5px; padding-right: 3px; }
.tx-grid th.tx-day { border-left: 1px solid #355a96; }
.tx-grid td { font-size: 8pt; height: 28px; border-top: 1px solid #c9d8ee; border-left: 1px solid #dbe6f5; color: #12306a; }
.tx-grid td:first-child { border-left: 0; }
.tx-c { text-align: center; font-weight: bold; }
.tx-name { font-weight: bold; font-size: 8pt; color: #0f2a52; }
.tx-id { font-size: 6.4pt; color: #5b6f8f; margin-top: 1px; }
.tx-mono { font-size: 8pt; }

.tx-dn { font-size: 7pt; font-weight: bold; }
.tx-off-h { background: #1b4079; }

.tx-cell { text-align: center; font-weight: bold; padding: 0; }
.tx-grid td.tx-off { background: #eaf1fc; }
.tx-grid td.tx-p { color: #16a34a; }
.tx-grid td.tx-a { color: #dc2626; }
.tx-grid td.tx-b { color: #1d4ed8; }

.tx-grid th.tx-sum-h { font-size: 6.6pt; border-left: 1px solid #355a96; }
.tx-sum { text-align: center; font-weight: bold; font-size: 10.5pt; }
.tx-grid td.tx-sum { background: #eef4fd; }
.tx-grid td.tx-sum-p { color: #16a34a; }
.tx-grid td.tx-sum-a { color: #dc2626; }

.tx-group td { background: #f1f6fd; font-weight: bold; font-size: 8pt; text-align: left; padding: 4px 8px; height: auto; color: #12306a; }

.tx-att table.tx-legend { border-collapse: separate; border-spacing: 0; margin-top: 12px; background: #e8f0fc; border: 1px solid #d3e1f6; border-radius: 12px; }
.tx-lg { font-size: 6.8pt; color: #12306a; padding: 8px 8px; border-left: 1px solid #1b4079; }
.tx-lg:first-child { border-left: 0; }
.tx-lc { font-size: 10.5pt; font-weight: bold; color: #1d4ed8; margin-right: 3px; }
.tx-lg-p { color: #16a34a; }
.tx-lg-a { color: #dc2626; }
.tx-note { margin-top: 4px; font-size: 6.2pt; color: #5b6f8f; }

.tx-page { height: auto; }
.tx-page-body { vertical-align: top; padding: 0; }
.tx-page-foot { vertical-align: top; padding: 0; }
.tx-sign { margin-top: 12mm; page-break-inside: avoid; }
.tx-sign-cell { width: 48%; vertical-align: top; }
.tx-sign-gap { width: 4%; text-align: center; }
.tx-sign-vline { border-left: 2px solid #1b5fbf; height: 62px; width: 0; margin: 0 auto; }
.tx-att table.tx-sign-bar { border-collapse: separate; border-spacing: 0; background: #e8f0fc; border: 1px solid #d3e1f6; border-radius: 12px; }
.tx-sign-ico { width: 1%; padding: 6px 10px 6px 8px; }
.tx-circle { display: inline-block; width: 36px; height: 36px; border-radius: 50%; background: #12306a; text-align: center; line-height: 40px; }
.tx-circle svg { vertical-align: middle; }
.tx-sign-label { font-size: 11pt; font-weight: bold; color: #12306a; padding-right: 10px; }
.tx-att table.tx-sign-sub { width: 100%; border-collapse: collapse; margin: 14px 0 0 0; font-size: 9pt; color: #12306a; white-space: nowrap; }
.tx-sign-sub td.tx-sk { width: 1%; padding: 0 6px 0 4px !important; vertical-align: bottom !important; }
.tx-sign-sub td.tx-sl { height: 20px; border-bottom: 1px solid #12306a; padding: 0 !important; }
.tx-sign-sub td.tx-sl-n { width: 52%; }
.tx-sign-sub td.tx-sl-d { width: 30%; }
.tx-sign-sub td.tx-sg { width: 4%; padding: 0 !important; }
.tx-ln { display: inline-block; border-bottom: 1px solid #12306a; height: 10px; vertical-align: baseline; }
.tx-ln-n { width: 160px; }
.tx-ln-d { width: 110px; }

@page { size: A4 landscape; margin: 10mm; }

/* ---- Override Frappe's global ".print-format td/th { padding: 6px !important; vertical-align: top !important }" ---- */
.tx-att table td, .tx-att table th { padding: 0 !important; vertical-align: middle !important; }
.tx-att table td.tx-bar { padding: 7px 14px !important; }
.tx-att table td.tx-bar-info { padding: 5px 14px !important; }
.tx-att table td.tx-ico { padding: 0 12px 0 0 !important; }
.tx-att table td.tx-ico-s { padding: 0 6px 0 0 !important; }
.tx-att table td.tx-vdiv { padding: 0 !important; }
.tx-att table td.tx-vdiv + td { padding-left: 14px !important; }
.tx-att table td.tx-vdiv-s + td { padding-left: 16px !important; }
.tx-att table td.tx-meta-cell { padding-right: 16px !important; }
.tx-att table td.tx-bar-gap { padding: 0 !important; }
.tx-att table.tx-grid th, .tx-att table.tx-grid td { padding: 3px 2px !important; }
.tx-att table.tx-grid th.tx-left, .tx-att table.tx-grid td.tx-left { padding: 3px 3px 3px 6px !important; text-align: left !important; }
.tx-att table.tx-grid td.tx-cell { padding: 0 !important; }
.tx-att table.tx-grid tr.tx-group td { padding: 4px 8px !important; }
.tx-att table td.tx-lg { padding: 8px 8px !important; }
.tx-att table td.tx-page-body { padding: 0 !important; vertical-align: top !important; }
.tx-att table td.tx-page-foot { padding: 0 !important; vertical-align: top !important; }
.tx-att table td.tx-sign-cell { padding: 0 !important; vertical-align: top !important; }
.tx-att table td.tx-sign-gap { padding: 0 !important; vertical-align: top !important; }
.tx-att table td.tx-sign-ico { padding: 6px 10px 6px 8px !important; }
.tx-att table td.tx-sign-label { padding: 0 10px 0 0 !important; }
.tx-att table.tx-grid th { white-space: nowrap; }

/* top spacing so the logo is not flush with the page edge */
.tx-att { padding: 8mm 6mm 0 6mm; }


/* ---- polish: zebra rows, muted placeholders ---- */
.tx-grid tbody tr:nth-child(even):not(.tx-group) td:not(.tx-off):not(.tx-sum) { background: #f7faff; }
.tx-dash { color: #9aabc6; }
.tx-att table.tx-grid th.tx-day { padding: 3px 0 !important; }

