{%
var MONTHS = [__("January"), __("February"), __("March"), __("April"), __("May"), __("June"), __("July"), __("August"), __("September"), __("October"), __("November"), __("December")];
var WEEKDAYS = [__("Sun"), __("Mon"), __("Tue"), __("Wed"), __("Thu"), __("Fri"), __("Sat")];
var esc = frappe.utils.escape_html;
var CLS = { P: "tx-p", A: "tx-a", L: "tx-b", WFH: "tx-b", "HD/P": "tx-b", "HD/A": "tx-b", WO: "tx-b", H: "tx-b" };

var day_cols = [];
for (var c = 0; c < columns.length; c++) {
	var fname = columns[c].fieldname;
	if (fname && fname.split("-").length === 3) { day_cols.push(columns[c]); }
}

var emp_rows = [];
for (var r = 0; r < data.length; r++) {
	if (data[r].employee) { emp_rows.push(data[r]); }
}

var day_info = [];
for (var k = 0; k < day_cols.length; k++) {
	var parts = day_cols[k].fieldname.split("-");
	var dt = new Date(cint(parts[2]), cint(parts[1]) - 1, cint(parts[0]));
	var is_off = emp_rows.length > 0;
	for (var e = 0; e < emp_rows.length; e++) {
		var code0 = emp_rows[e][day_cols[k].fieldname];
		if (code0 !== "WO" && code0 !== "H") { is_off = false; }
	}
	day_info.push({ day: cint(parts[0]), weekday: WEEKDAYS[dt.getDay()], off: is_off });
}

var tally = function (row) {
	if (!day_cols.length && row.total_present !== undefined && row.total_present !== null) {
		return { p: flt(row.total_present), a: flt(row.total_absent) };
	}
	var p = 0, a = 0;
	for (var i = 0; i < day_cols.length; i++) {
		var code = row[day_cols[i].fieldname];
		if (code === "P" || code === "WFH") { p += 1; }
		else if (code === "HD/P") { p += 0.5; }
		else if (code === "HD/A") { a += 0.5; }
		else if (code === "A") { a += 1; }
	}
	return { p: p, a: a };
};
var fmt = function (n) { return n === Math.floor(n) ? String(n) : n.toFixed(1); };

var period = "";
if (filters.filter_based_on === "Date Range" && filters.start_date && filters.end_date) {
	period = frappe.datetime.str_to_user(filters.start_date) + "  -  " + frappe.datetime.str_to_user(filters.end_date);
} else if (filters.month && filters.year) {
	period = MONTHS[cint(filters.month) - 1] + " " + filters.year;
}

var meta = [];
if (filters.company) { meta.push([__("Company"), filters.company]); }
if (filters.branch) { meta.push([__("Branch"), filters.branch]); }
if (filters.department) { meta.push([__("Department"), filters.department]); }
if (filters.designation) { meta.push([__("Designation"), filters.designation]); }
if (filters.employee) { meta.push([__("Employee"), filters.employee]); }
if (filters.status) { meta.push([__("Status"), filters.status]); }

var gkey = filters.group_by ? frappe.scrub(filters.group_by) : null;
var n_days = day_cols.length;
var day_w = n_days ? (50 / n_days) : 0;
var day_fs = n_days > 31 ? 5 : 7;
var code_fs = function (v) { return v.indexOf("/") > -1 ? day_fs - 1.4 : (v.length <= 1 ? day_fs : (v.length === 2 ? day_fs - 1.2 : day_fs - 2)); };
var code_html = function (v) { var s = v.split("/"); return s.length > 1 ? esc(s[0]) + "<br>" + esc(s[1]) : esc(v); };
var total_cols = 7 + n_days;
var sn = 0;
var printed_on = frappe.datetime.str_to_user(frappe.datetime.get_today());
var logo_src = "data:image/png;base64,";
%}

<div class="tx-att">
<table class="tx-page"><tr><td class="tx-page-body">

	<div class="tx-logo-row"><img class="tx-logo" src="{{ logo_src }}" alt="tareqix" width="168" height="56" style="width: 168px !important; height: 56px !important; max-width: none !important; max-height: none !important; object-fit: contain;"></div>
	<div class="tx-rule"></div>

	<table class="tx-bars">
		<tr>
			<td class="tx-bar tx-bar-title">
				<table class="tx-inner"><tr>
					<td class="tx-ico">
						<svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#1b4079" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M8 3v4M16 3v4M3 10h18"/><path d="M7.5 14h2M11 14h2M14.5 14h2M7.5 17.5h2M11 17.5h2M14.5 17.5h2" stroke-width="2.2"/></svg>
					</td>
					<td class="tx-vdiv"></td>
					<td>
						<div class="tx-title">{{ __("Monthly Attendance Sheet") }}</div>
						{% if (period) { %}<div class="tx-period">{{ esc(period) }}</div>{% } %}
					</td>
				</tr></table>
			</td>
			<td class="tx-bar-gap"></td>
			<td class="tx-bar tx-bar-print">
				<table class="tx-inner"><tr>
					<td class="tx-ico">
						<svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#1b4079" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 9V3h10v6"/><rect x="3" y="9" width="18" height="9" rx="2"/><rect x="7" y="14" width="10" height="7" rx="1" fill="#fff"/></svg>
					</td>
					<td>
						<div class="tx-printed-k">{{ __("Printed on") }}:</div>
						<div class="tx-printed-v">{{ esc(printed_on) }}</div>
					</td>
				</tr></table>
			</td>
		</tr>
	</table>

	{% if (meta.length) { %}
	<table class="tx-bars tx-infobar"><tr><td class="tx-bar tx-bar-info">
		<table class="tx-inner"><tr>
			{% for (var m = 0; m < meta.length; m++) { %}
			{% if (m > 0) { %}<td class="tx-vdiv tx-vdiv-s"></td>{% } %}
			{% if (meta[m][0] === __("Company")) { %}
			<td class="tx-ico tx-ico-s"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#1b4079" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 21V4a1 1 0 0 1 1-1h9a1 1 0 0 1 1 1v17M15 9h4a1 1 0 0 1 1 1v11M2 21h20M8 7h3M8 11h3M8 15h3"/></svg></td>
			{% } else if (meta[m][0] === __("Status")) { %}
			<td class="tx-ico tx-ico-s"><svg width="22" height="22" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11" fill="#16a34a"/><path d="M7 12.5l3.5 3.5L17 9" fill="none" stroke="#fff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg></td>
			{% } %}
			<td class="tx-meta-cell"><span class="tx-meta-k">{{ esc(meta[m][0]) }}:</span> <span class="tx-meta-v{% if (meta[m][1] === 'Active') { %} tx-meta-active{% } %}">{{ esc(meta[m][1]) }}</span></td>
			{% } %}
		</tr></table>
	</td></tr></table>
	{% } %}

	<div class="tx-grid-wrap">
	<table class="tx-grid">
		<colgroup>
			<col style="width: 2.2%">
			<col style="width: 13.5%">
			<col style="width: 8%">
			<col style="width: 7.5%">
			<col style="width: 7.5%">
			{% for (var cg = 0; cg < n_days; cg++) { %}<col style="width: {{ day_w }}%">{% } %}
			<col style="width: 5.6%">
			<col style="width: 5.6%">
		</colgroup>
		<thead>
			<tr>
				<th>#</th>
				<th class="tx-left">{{ __("Employee") }}</th>
				<th class="tx-left">{{ __("Designation") }}</th>
				<th class="tx-left">{{ __("Nationality") }}</th>
				<th class="tx-left">{{ __("Civil ID") }}</th>
				{% for (var h = 0; h < n_days; h++) { %}
				<th class="tx-day{% if (day_info[h].off) { %} tx-off-h{% } %}">
					<div class="tx-dn">{{ day_info[h].day }}</div>
				</th>
				{% } %}
				<th class="tx-sum-h">{{ __("Present") }}</th>
				<th class="tx-sum-h">{{ __("Absent") }}</th>
			</tr>
		</thead>
		<tbody>
			{% for (var i = 0; i < data.length; i++) { %}
				{% var row = data[i]; %}
				{% if (!row.employee) { %}
					{% var glabel = gkey && row[gkey] ? row[gkey] : ""; %}
					{% if (glabel) { %}
					<tr class="tx-group"><td colspan="{{ total_cols }}">{{ esc(__(filters.group_by)) }}: {{ esc(glabel) }}</td></tr>
					{% } %}
				{% } else { %}
					{% sn += 1; %}
					{% var t = tally(row); %}
					<tr>
						<td class="tx-c">{{ sn }}</td>
						<td class="tx-left"><div class="tx-name">{{ esc(row.employee_name || "") }}</div><div class="tx-id">{{ esc(row.employee) }}</div></td>
						<td class="tx-left">{{ row.emp_designation ? esc(row.emp_designation) : '<span class="tx-dash">-</span>' }}</td>
						<td class="tx-left">{{ row.emp_nationality ? esc(row.emp_nationality) : '<span class="tx-dash">-</span>' }}</td>
						<td class="tx-left tx-mono">{{ row.emp_civil_id ? esc(row.emp_civil_id) : '<span class="tx-dash">-</span>' }}</td>
						{% for (var d = 0; d < n_days; d++) { %}
							{% var v = row[day_cols[d].fieldname] || ""; %}
							<td class="tx-cell {{ CLS[v] || "" }}{% if (day_info[d].off) { %} tx-off{% } %}" style="font-size: {{ code_fs(v) }}pt; line-height: 1.05">{{ code_html(v) }}</td>
						{% } %}
						<td class="tx-sum tx-sum-p">{{ fmt(t.p) }}</td>
						<td class="tx-sum tx-sum-a">{{ fmt(t.a) }}</td>
					</tr>
				{% } %}
			{% } %}
		</tbody>
	</table>
	</div>

	<table class="tx-legend"><tr>
		<td class="tx-lg"><span class="tx-lc tx-lg-p">P</span> {{ __("Present") }}</td>
		<td class="tx-lg"><span class="tx-lc tx-lg-a">A</span> {{ __("Absent") }}</td>
		<td class="tx-lg"><span class="tx-lc">HD/P</span> {{ __("Half Day, Other Half Present") }}</td>
		<td class="tx-lg"><span class="tx-lc">HD/A</span> {{ __("Half Day, Other Half Absent") }}</td>
		<td class="tx-lg"><span class="tx-lc">WFH</span> {{ __("Work From Home") }}</td>
		<td class="tx-lg"><span class="tx-lc">L</span> {{ __("On Leave") }}</td>
		<td class="tx-lg"><span class="tx-lc">H</span> {{ __("Holiday") }}</td>
		<td class="tx-lg"><span class="tx-lc">WO</span> {{ __("Weekly Off") }}</td>
	</tr></table>
	<div class="tx-note">{{ __("Present counts Present, Work From Home and half days worked (0.5 each). Absent counts Absent days and absent half days (0.5 each).") }}</div>

</td></tr>
<tr><td class="tx-page-foot">
	<table class="tx-sign">
		<tr>
			<td class="tx-sign-cell">
				<table class="tx-sign-bar"><tr>
					<td class="tx-sign-ico"><span class="tx-circle"><svg width="22" height="22" viewBox="0 0 24 24" fill="#fff"><circle cx="12" cy="8" r="4.2"/><path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7z"/></svg></span></td>
					<td class="tx-sign-label">{{ __("Department Head / Supervisor Signature") }}</td>
				</tr></table>
				<table class="tx-sign-sub"><tr><td class="tx-sk">{{ __("Name") }}:</td><td class="tx-sl tx-sl-n"></td><td class="tx-sg"></td><td class="tx-sk">{{ __("Date") }}:</td><td class="tx-sl tx-sl-d"></td></tr></table>
			</td>
			<td class="tx-sign-gap"><div class="tx-sign-vline"></div></td>
			<td class="tx-sign-cell">
				<table class="tx-sign-bar"><tr>
					<td class="tx-sign-ico"><span class="tx-circle"><svg width="24" height="24" viewBox="0 0 24 24" fill="#fff"><circle cx="12" cy="8" r="3.6"/><path d="M5 20c0-3.8 3.1-6 7-6s7 2.2 7 6z"/><circle cx="4.8" cy="9.5" r="2.4"/><circle cx="19.2" cy="9.5" r="2.4"/></svg></span></td>
					<td class="tx-sign-label">{{ __("HR Signature") }}</td>
				</tr></table>
				<table class="tx-sign-sub"><tr><td class="tx-sk">{{ __("Name") }}:</td><td class="tx-sl tx-sl-n"></td><td class="tx-sg"></td><td class="tx-sk">{{ __("Date") }}:</td><td class="tx-sl tx-sl-d"></td></tr></table>
			</td>
		</tr>
	</table>
</td></tr></table>

</div>

