{%
var MONTHS = [__("January"), __("February"), __("March"), __("April"), __("May"), __("June"), __("July"), __("August"), __("September"), __("October"), __("November"), __("December")];
var WEEKDAYS = [__("Sun"), __("Mon"), __("Tue"), __("Wed"), __("Thu"), __("Fri"), __("Sat")];
var esc = frappe.utils.escape_html;

var pad = function(n) {
	return n < 10 ? "0" + n : String(n);
};

/* Convert seconds into HH:MM Hrs */
/* Compact hours format */


/* Daily display: 9, 6, 5.30 */
var format_day_hours = function(seconds) {
	var total_minutes = Math.round((seconds || 0) / 60);
	var hours = Math.floor(total_minutes / 60);
	var minutes = total_minutes % 60;

	if (minutes === 0) {
		return String(hours);
	}

	return hours + "." + pad(minutes);
};

/* Final totals: 9hrs, 5.30hrs */
var format_hours = function(seconds) {
	return format_day_hours(seconds) + "hrs";
};





/* Convert report Hours (Float) into seconds */
var get_work_seconds = function(value) {
	return Math.round(flt(value || 0) * 3600);
};

/* Convert Rest Hours (HH:MM:SS) into seconds */
var get_rest_seconds = function(value) {
	if (!value) return 0;

	var parts = String(value).split(":");

	if (parts.length === 3) {
		return cint(parts[0]) * 3600 +
			cint(parts[1]) * 60 +
			Math.round(flt(parts[2]));
	}

	if (parts.length === 2) {
		return cint(parts[0]) * 3600 +
			cint(parts[1]) * 60;
	}

	return 0;
};

/* Normalize report date to DD-MM-YYYY */
var date_key = function(value) {
	var s = String(value || "").substring(0, 10);
	var p = s.split("-");

	if (p.length !== 3) return "";

	if (p[0].length === 4) {
		return p[2] + "-" + p[1] + "-" + p[0];
	}

	return s;
};

/* Generate all date columns from report filters */
var day_cols = [];
var day_info = [];

var start_date = filters.from_date;
var end_date = filters.to_date;

if (start_date && end_date) {
	var sp = String(start_date).split("-");
	var ep = String(end_date).split("-");

	var current = new Date(
		cint(sp[0]),
		cint(sp[1]) - 1,
		cint(sp[2])
	);

	var last = new Date(
		cint(ep[0]),
		cint(ep[1]) - 1,
		cint(ep[2])
	);

	while (current <= last) {
		var dd = pad(current.getDate());
		var mm = pad(current.getMonth() + 1);
		var yyyy = current.getFullYear();

		var fname = dd + "-" + mm + "-" + yyyy;

		day_cols.push({ fieldname: fname });

		day_info.push({
			day: current.getDate(),
			weekday: WEEKDAYS[current.getDay()],
			off: false
		});

		current.setDate(current.getDate() + 1);
	}
}

/* Combine daily report rows into one row per employee */
var emp_rows = [];
var emp_map = {};

for (var r = 0; r < data.length; r++) {
	var source = data[r];

	if (!source.employee) continue;

	var emp_id = source.employee;

	if (!emp_map[emp_id]) {
		var emp = Object.assign({}, source);

		emp.daily = {};
		emp.total_work_seconds = 0;
		emp.total_rest_seconds = 0;

		emp_map[emp_id] = emp;
		emp_rows.push(emp);
	}

	var employee_row = emp_map[emp_id];
	var key = date_key(source.date);

	if (!key) continue;

	if (!employee_row.daily[key]) {
		employee_row.daily[key] = {
			work_seconds: 0,
			rest_seconds: 0
		};
	}

	var work_seconds = get_work_seconds(source.hours);
	var rest_seconds = get_rest_seconds(source.rest_hours);

	employee_row.daily[key].work_seconds += work_seconds;
	employee_row.daily[key].rest_seconds += rest_seconds;

	employee_row.total_work_seconds += work_seconds;
	employee_row.total_rest_seconds += rest_seconds;
}

/* Period title */
var period = "";

if (filters.from_date && filters.to_date) {
	period = frappe.datetime.str_to_user(filters.from_date) +
		"  -  " +
		frappe.datetime.str_to_user(filters.to_date);
} else if (filters.month && filters.year) {
	period = MONTHS[cint(filters.month) - 1] + " " + filters.year;
}

/* Existing filter information */
var meta = [];

if (filters.company) { meta.push([__("Company"), filters.company]); }
if (filters.branch) { meta.push([__("Branch"), filters.branch]); }
if (filters.department) { meta.push([__("Department"), filters.department]); }
if (filters.designation) { meta.push([__("Designation"), filters.designation]); }
if (filters.employee) { meta.push([__("Employee"), filters.employee]); }
if (filters.status) { meta.push([__("Status"), filters.status]); }

var gkey = null;
var n_days = day_cols.length;
var day_w = n_days ? (50 / n_days) : 0;
var day_fs = n_days > 31 ? 5 : 7;

var total_cols = 7 + n_days;
var sn = 0;

var printed_on = frappe.datetime.str_to_user(frappe.datetime.get_today());
var logo_src = "564hd78ttuigt78yrfjkh37r"
%}


